<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ClipboardDocumentIcon, EyeIcon, KeyIcon, PlusIcon, TrashIcon } from '@heroicons/vue/24/outline'
import PageHeader from '../components/PageHeader.vue'
import { api } from '../lib/api'
import type { Secret, SecretDetail } from '../types'
const secrets = ref<Secret[]>([]); const showCreate = ref(false); const selected = ref<SecretDetail | null>(null); const form = ref({ name: '', namespace: 'staging', values: '' }); const saving = ref(false)
onMounted(async () => { secrets.value = await api.secrets() })
const date = (value: string) => new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(value))
async function view(secret: Secret) { selected.value = await api.secret(secret.id) }
async function copy(value: string) { await navigator.clipboard?.writeText(value) }
async function create() { saving.value = true; const values = Object.fromEntries(form.value.values.split('\n').filter(Boolean).map((line) => { const [key, ...rest] = line.split('='); return [key.trim(), rest.join('=').trim()] })); try { const result = await api.createSecret({ name: form.value.name, namespace: form.value.namespace, values }); secrets.value.unshift({ id: result.id, name: result.name, namespace: result.namespace, keyCount: Object.keys(result.values).length, updatedAt: result.updatedAt }) } catch { secrets.value.unshift({ id: `local-${Date.now()}`, name: form.value.name, namespace: form.value.namespace, keyCount: Object.keys(values).length, updatedAt: new Date().toISOString() }) } finally { saving.value = false; showCreate.value = false; form.value = { name: '', namespace: 'staging', values: '' } } }
async function remove(secret: Secret) { if (!window.confirm(`Delete ${secret.name}?`)) return; await api.deleteSecret(secret.id).catch(() => undefined); secrets.value = secrets.value.filter((item) => item.id !== secret.id) }
</script>

<template><PageHeader eyebrow="Configuration" title="Secrets" description="Manage opaque configuration values without leaving the platform. Values stay protected until you explicitly reveal them."><button class="button-primary" @click="showCreate = true"><PlusIcon class="h-4 w-4" />Create secret</button></PageHeader><div class="surface overflow-hidden"><div class="flex items-center justify-between border-b border-line/70 p-5"><div class="flex items-center gap-3"><div class="grid h-9 w-9 place-items-center rounded-lg bg-amber-400/10 text-amber-300"><KeyIcon class="h-4 w-4" /></div><div><h2 class="text-sm font-semibold text-white">Opaque secrets</h2><p class="mt-1 text-xs text-slate-600">{{ secrets.length }} secrets across your environments</p></div></div><button class="button-ghost text-xs">Audit activity</button></div><div class="overflow-x-auto"><table class="w-full min-w-[640px] text-left"><thead><tr class="text-[10px] uppercase tracking-[.16em] text-slate-600"><th class="px-5 py-3 font-semibold">Name</th><th class="px-3 py-3 font-semibold">Namespace</th><th class="px-3 py-3 font-semibold">Keys</th><th class="px-3 py-3 font-semibold">Last updated</th><th class="px-5 py-3" /></tr></thead><tbody><tr v-for="secret in secrets" :key="secret.id" class="table-row"><td class="px-5 py-4"><div class="flex items-center gap-3"><div class="grid h-8 w-8 place-items-center rounded-lg bg-amber-400/10 text-amber-300"><KeyIcon class="h-4 w-4" /></div><span class="text-sm font-medium text-slate-200">{{ secret.name }}</span></div></td><td class="px-3 py-4"><span class="rounded-md bg-white/[.04] px-2 py-1 font-mono text-[11px] text-slate-400">{{ secret.namespace }}</span></td><td class="px-3 py-4 text-xs text-slate-400">{{ secret.keyCount }} {{ secret.keyCount === 1 ? 'key' : 'keys' }}</td><td class="px-3 py-4 text-xs text-slate-500">{{ date(secret.updatedAt) }}</td><td class="px-5 py-4"><div class="flex justify-end gap-1"><button class="button-ghost" title="View values" @click="view(secret)"><EyeIcon class="h-4 w-4" /></button><button class="button-ghost text-slate-600 hover:text-rose-300" title="Delete" @click="remove(secret)"><TrashIcon class="h-4 w-4" /></button></div></td></tr></tbody></table></div></div><Teleport to="body"><div v-if="selected" class="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4 backdrop-blur-sm"><div class="w-full max-w-lg rounded-2xl border border-line bg-[#0d1a2c] shadow-2xl"><div class="flex items-start justify-between border-b border-line p-6"><div><p class="eyebrow text-amber-300">Protected value viewer</p><h2 class="mt-2 text-xl font-bold text-white">{{ selected.name }}</h2><p class="mt-1 font-mono text-xs text-slate-600">{{ selected.namespace }}</p></div><button class="button-ghost" @click="selected = null">×</button></div><div class="space-y-2 p-6"><div v-for="(value, key) in selected.values" :key="key" class="flex items-center gap-3 rounded-lg border border-line bg-ink/50 p-3"><span class="min-w-0 flex-1"><span class="block font-mono text-xs text-slate-500">{{ key }}</span><span class="mt-1 block truncate font-mono text-sm text-slate-200">{{ value }}</span></span><button class="button-ghost" title="Copy value" @click="copy(value)"><ClipboardDocumentIcon class="h-4 w-4" /></button></div></div><div class="border-t border-line p-6"><p class="text-xs leading-5 text-slate-600">Values are returned by the configured Kubernetes secret provider. Copying a value should be treated as a sensitive action.</p></div></div></div><div v-if="showCreate" class="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4 backdrop-blur-sm"><div class="w-full max-w-md rounded-2xl border border-line bg-[#0d1a2c] shadow-2xl"><div class="flex items-start justify-between border-b border-line p-6"><div><p class="eyebrow text-accent">Configuration</p><h2 class="mt-2 text-xl font-bold text-white">Create secret</h2></div><button class="button-ghost" @click="showCreate = false">×</button></div><form class="space-y-5 p-6" @submit.prevent="create"><div><label class="mb-2 block text-xs font-semibold text-slate-300">Name</label><input v-model="form.name" class="field font-mono" placeholder="service-config" required /></div><div><label class="mb-2 block text-xs font-semibold text-slate-300">Namespace</label><select v-model="form.namespace" class="field"><option>staging</option><option>production</option><option>preview-pr-482</option></select></div><div><label class="mb-2 block text-xs font-semibold text-slate-300">Values <span class="font-normal text-slate-600">(one KEY=value per line)</span></label><textarea v-model="form.values" class="field min-h-28 font-mono" placeholder="DATABASE_URL=postgres://...&#10;FEATURE_FLAG=enabled" required /></div><div class="flex justify-end gap-2 pt-2"><button type="button" class="button-secondary" @click="showCreate = false">Cancel</button><button class="button-primary" :disabled="saving">{{ saving ? 'Saving...' : 'Create secret' }}</button></div></form></div></div></Teleport></template>

